CREATE TABLE `access_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned DEFAULT NULL,
  `login_id` varchar(255) NOT NULL COMMENT 'Login ID (email or username used for login attempt)',
  `ip_address` varchar(45) NOT NULL COMMENT 'IP address',
  `browser_info` varchar(255) DEFAULT NULL COMMENT 'Browser information (e.g., Chrome 131.0 - Windows 10)',
  `user_agent` text COMMENT 'Full user agent string',
  `event_type` varchar(50) NOT NULL COMMENT 'Event type: login, logout, login_failed',
  `management` varchar(50) DEFAULT NULL COMMENT 'Management/Action type (e.g., Login failed, log out, log in)',
  `explanation` text COMMENT 'Explanation/Description (e.g., Invalid credentials provided)',
  `connection_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'Connection/Access timestamp',
  `access_date` date NOT NULL COMMENT 'Access date (for grouping/filtering)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `access_logs_user_id_connection_time_index` (`user_id`,`connection_time`),
  KEY `access_logs_login_id_connection_time_index` (`login_id`,`connection_time`),
  KEY `access_logs_ip_address_connection_time_index` (`ip_address`,`connection_time`),
  KEY `access_logs_event_type_connection_time_index` (`event_type`,`connection_time`),
  KEY `access_logs_login_id_index` (`login_id`),
  KEY `access_logs_ip_address_index` (`ip_address`),
  KEY `access_logs_event_type_index` (`event_type`),
  KEY `access_logs_connection_time_index` (`connection_time`),
  KEY `access_logs_access_date_index` (`access_date`),
  CONSTRAINT `access_logs_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=411 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
