--
-- Table structure for table `address_books`
--

DROP TABLE IF EXISTS `address_books`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `address_books` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `name` varchar(100) NOT NULL COMMENT '배송지명 (Delivery Address Name)',
  `recipient` varchar(100) NOT NULL COMMENT '수령자 (Recipient)',
  `phone` varchar(20) DEFAULT NULL COMMENT '전화번호 (Phone Number)',
  `mobile` varchar(20) DEFAULT NULL COMMENT '핸드폰 (Mobile Phone)',
  `email` varchar(255) DEFAULT NULL COMMENT '배송지 연락 이메일 (optional)',
  `postcode` varchar(10) DEFAULT NULL COMMENT '우편번호 (Postal Code)',
  `address` varchar(255) DEFAULT NULL COMMENT '주소 (Address)',
  `detailed_address` varchar(255) DEFAULT NULL COMMENT '상세 주소 (Detailed Address)',
  `is_default` tinyint(1) NOT NULL DEFAULT '0' COMMENT '기본 배송지 (Default Delivery Address)',
  `delivery_message` varchar(255) DEFAULT NULL COMMENT '배송 메시지 (Delivery Message)',
  `delivery_message_preset` varchar(255) DEFAULT NULL COMMENT '배송 메시지 프리셋 (Delivery Message Preset)',
  `delivery_message_custom` varchar(255) DEFAULT NULL COMMENT '직접 입력 배송 메시지 (Custom Delivery Message)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `address_books_user_id_index` (`user_id`),
  KEY `address_books_user_id_is_default_index` (`user_id`,`is_default`),
  CONSTRAINT `address_books_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
