--
-- Table structure for table `delivery_trackings`
--

DROP TABLE IF EXISTS `delivery_trackings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `delivery_trackings` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `invoice_number` varchar(255) NOT NULL COMMENT '송장번호',
  `waybill_registered_at` date DEFAULT NULL COMMENT '송장 등록일',
  `delivery_status` varchar(50) NOT NULL DEFAULT 'pickup' COMMENT '배송 상태: pickup, in_transit, delivered',
  `courier_name` varchar(255) DEFAULT NULL COMMENT '배송 업체',
  `tracking_info` json DEFAULT NULL COMMENT '추적 정보',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `delivery_trackings_order_id_foreign` (`order_id`),
  KEY `delivery_trackings_delivery_status_waybill_registered_at_index` (`delivery_status`,`waybill_registered_at`),
  CONSTRAINT `delivery_trackings_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

