--
-- Table structure for table `direct_shipping_requests`
--

DROP TABLE IF EXISTS `direct_shipping_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `direct_shipping_requests` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `shipping_name` varchar(255) NOT NULL COMMENT '배송지명',
  `recipient_name` varchar(255) NOT NULL COMMENT '이름',
  `phone` varchar(255) DEFAULT NULL COMMENT '전화번호',
  `postcode` varchar(255) DEFAULT NULL COMMENT '우편번호',
  `address` varchar(255) DEFAULT NULL COMMENT '주소',
  `detailed_address` varchar(255) DEFAULT NULL COMMENT '상세 주소',
  `storage_location` varchar(255) DEFAULT NULL COMMENT '보관장소',
  `file_path` varchar(255) DEFAULT NULL COMMENT '업로드 파일 경로',
  `file_name` varchar(255) DEFAULT NULL COMMENT '업로드 파일 원본명',
  `detail_request` text NOT NULL COMMENT '상세요청',
  `amount` bigint unsigned NOT NULL DEFAULT '0' COMMENT '입금액 (VAT 포함)',
  `status` varchar(255) NOT NULL DEFAULT 'pending' COMMENT 'pending|confirmed|completed|cancelled',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `direct_shipping_requests_user_id_foreign` (`user_id`),
  CONSTRAINT `direct_shipping_requests_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `direct_shipping_requests`
--

LOCK TABLES `direct_shipping_requests` WRITE;
