DROP TABLE IF EXISTS `faqs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `faqs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category` varchar(100) DEFAULT NULL COMMENT 'FAQ category: order, payment, delivery, etc.',
  `question` varchar(500) NOT NULL COMMENT 'The frequently asked question',
  `answer` text NOT NULL COMMENT 'The detailed answer to the question',
  `sort_order` int NOT NULL DEFAULT '0' COMMENT 'Display priority (lower numbers shown first)',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Visibility status',
  `exposure_target` json DEFAULT NULL,
  `view_count` int NOT NULL DEFAULT '0' COMMENT 'Total number of times this FAQ was viewed',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `faqs_created_by_foreign` (`created_by`),
  KEY `faqs_category_index` (`category`),
  KEY `faqs_is_active_index` (`is_active`),
  KEY `faqs_sort_order_index` (`sort_order`),
  KEY `idx_faq_status_category_sort` (`is_active`,`category`,`sort_order`),
  CONSTRAINT `faqs_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

