--
-- Table structure for table `guide_contents`
--

DROP TABLE IF EXISTS `guide_contents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `guide_contents` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `title` varchar(255) NOT NULL COMMENT 'Guide title',
  `content` text NOT NULL COMMENT 'Main content of the Guide',
  `attachments` json DEFAULT NULL COMMENT 'JSON array of attached file paths',
  `type` varchar(50) NOT NULL DEFAULT 'general' COMMENT 'Type: PRODUCTION_GUIDE, PRECAUTION, SHIPPING, USAGE_GUIDE, etc.',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Active status for visibility',
  `published_at` timestamp NULL DEFAULT NULL COMMENT 'Date and time to start displaying the guide',
  `expires_at` timestamp NULL DEFAULT NULL COMMENT 'Date and time to stop displaying the guide',
  `exposure_target` json DEFAULT NULL COMMENT 'Visibility target: "all" or array of customer IDs',
  `created_by` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `guide_contents_type_index` (`type`),
  KEY `guide_contents_is_active_index` (`is_active`),
  KEY `guide_contents_published_at_index` (`published_at`),
  KEY `guide_contents_created_by_index` (`created_by`),
  KEY `idx_guide_content_status_visibility` (`is_active`,`published_at`,`created_by`),
  CONSTRAINT `guide_contents_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `guide_contents`
