DROP TABLE IF EXISTS `inquiries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inquiries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `product_id` bigint unsigned DEFAULT NULL,
  `category` varchar(255) NOT NULL COMMENT 'Inquiry category: product, payment, delivery, etc.',
  `title` varchar(255) NOT NULL,
  `content` text NOT NULL,
  `order_number` varchar(255) DEFAULT NULL COMMENT 'Associated order number if applicable',
  `contact` varchar(255) NOT NULL COMMENT 'User contact information',
  `manager_name` varchar(100) DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'pending' COMMENT 'pending, in_progress, completed',
  `replied_by` bigint unsigned DEFAULT NULL,
  `reply_contact_phone` varchar(255) DEFAULT NULL COMMENT 'Phone number used for the reply',
  `reply_content` text,
  `is_edited_reply` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Flag if the reply was modified after posting',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `inquiries_replied_by_foreign` (`replied_by`),
  KEY `inquiries_user_id_index` (`user_id`),
  KEY `inquiries_product_id_index` (`product_id`),
  KEY `inquiries_category_index` (`category`),
  KEY `inquiries_status_index` (`status`),
  KEY `inquiries_order_number_index` (`order_number`),
  CONSTRAINT `inquiries_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inquiries_replied_by_foreign` FOREIGN KEY (`replied_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inquiries_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

