DROP TABLE IF EXISTS `inquiry_attachments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inquiry_attachments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `inquiry_id` bigint unsigned NOT NULL,
  `comment_id` bigint unsigned DEFAULT NULL,
  `file_name` varchar(255) NOT NULL COMMENT 'Original name of the uploaded file',
  `file_path` varchar(255) NOT NULL COMMENT 'Storage path or S3 URL of the file',
  `file_type` varchar(50) DEFAULT NULL COMMENT 'MIME type or extension: PDF, JPEG, PNG, etc.',
  `file_size` bigint unsigned DEFAULT NULL COMMENT 'File size in bytes',
  `is_reply_attachment` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'True if attached by staff in the response',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `inquiry_attachments_inquiry_id_index` (`inquiry_id`),
  KEY `inquiry_attachments_comment_id_foreign` (`comment_id`),
  CONSTRAINT `inquiry_attachments_comment_id_foreign` FOREIGN KEY (`comment_id`) REFERENCES `inquiry_comments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inquiry_attachments_inquiry_id_foreign` FOREIGN KEY (`inquiry_id`) REFERENCES `inquiries` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=84 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

