--
-- Table structure for table `notices`
--

DROP TABLE IF EXISTS `notices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notices` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL COMMENT 'Notice title',
  `content` text NOT NULL COMMENT 'Main content of the notice',
  `attachments` json DEFAULT NULL COMMENT 'JSON array of attached file paths',
  `type` varchar(50) NOT NULL DEFAULT 'general' COMMENT 'Type: general, important, maintenance, etc.',
  `is_pinned` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Whether the notice is pinned to the top',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Active status for visibility',
  `view_count` int NOT NULL DEFAULT '0' COMMENT 'Total number of views',
  `published_at` timestamp NULL DEFAULT NULL COMMENT 'Date and time to start displaying the notice',
  `expires_at` timestamp NULL DEFAULT NULL COMMENT 'Date and time to stop displaying the notice',
  `exposure_target` json DEFAULT NULL COMMENT 'Visibility target: "all" or array of customer IDs',
  `exposure_location` varchar(50) DEFAULT NULL COMMENT 'Target UI location for display',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `notices_type_index` (`type`),
  KEY `notices_is_active_index` (`is_active`),
  KEY `notices_is_pinned_index` (`is_pinned`),
  KEY `notices_published_at_index` (`published_at`),
  KEY `notices_exposure_location_index` (`exposure_location`),
  KEY `notices_created_by_index` (`created_by`),
  KEY `idx_notice_status_visibility` (`is_active`,`is_pinned`,`published_at`),
  CONSTRAINT `notices_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

