DROP TABLE IF EXISTS `notification_templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification_templates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT 'Template name',
  `template_number` varchar(100) DEFAULT NULL COMMENT 'External template number / code',
  `trigger_event` varchar(100) DEFAULT NULL COMMENT 'Event that triggers this template, e.g. membership_level_upgrade, order_placed',
  `channel_configs` json NOT NULL COMMENT 'Channel configurations (email, notification talk, SMS)',
  `usage_status` enum('enabled','disabled') NOT NULL DEFAULT 'enabled' COMMENT 'Usage status',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `notification_templates_template_number_index` (`template_number`),
  KEY `notification_templates_usage_status_index` (`usage_status`),
  KEY `notification_templates_created_by_index` (`created_by`),
  KEY `notification_templates_created_at_index` (`created_at`),
  CONSTRAINT `notification_templates_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

