DROP TABLE IF EXISTS `order_artworks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_artworks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `side` varchar(50) DEFAULT NULL COMMENT 'Options: front, back, side_a, side_b',
  `layout_data` json DEFAULT NULL COMMENT 'Web editor serialized layout data (JSON)',
  `layout_s3_path` varchar(255) DEFAULT NULL COMMENT 'S3 path for KonvaJS layout JSON/SVG file',
  `logo_path` varchar(255) DEFAULT NULL COMMENT 'Path to uploaded logo file',
  `preview_image_path` varchar(255) DEFAULT NULL COMMENT 'Rendered preview thumbnail path',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `design_group_id` bigint unsigned DEFAULT NULL,
  `cutline_image_url` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `order_artworks_design_group_id_side_unique` (`design_group_id`,`side`),
  CONSTRAINT `order_artworks_design_group_id_foreign` FOREIGN KEY (`design_group_id`) REFERENCES `design_groups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=96 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

