DROP TABLE IF EXISTS `order_shipping_address_histories`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `order_shipping_address_histories` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_id` bigint unsigned NOT NULL,
  `address_book_id` bigint unsigned DEFAULT NULL,
  `changed_at` timestamp NOT NULL,
  `payload` json NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `order_shipping_address_histories_address_book_id_foreign` (`address_book_id`),
  KEY `order_shipping_address_histories_order_id_changed_at_index` (`order_id`,`changed_at`),
  CONSTRAINT `order_shipping_address_histories_address_book_id_foreign` FOREIGN KEY (`address_book_id`) REFERENCES `address_books` (`id`) ON DELETE SET NULL,
  CONSTRAINT `order_shipping_address_histories_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
