--
-- Table structure for table `papers`
--

DROP TABLE IF EXISTS `papers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `papers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category` varchar(255) NOT NULL,
  `manufacturer` varchar(255) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `specification` json DEFAULT NULL,
  `paper_type_option_value_id` bigint unsigned DEFAULT NULL,
  `paper_color_option_value_id` bigint unsigned DEFAULT NULL,
  `paper_weight_option_value_id` bigint unsigned DEFAULT NULL,
  `colors` json DEFAULT NULL,
  `pattern` varchar(255) DEFAULT NULL,
  `basis_weights` json DEFAULT NULL,
  `grammage_data` json DEFAULT NULL COMMENT '책등/중량 계산용 평량별 데이터 (grammage → thickness_mm, weight_g)',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `papers_created_by_foreign` (`created_by`),
  KEY `papers_paper_type_option_value_id_foreign` (`paper_type_option_value_id`),
  KEY `papers_paper_color_option_value_id_foreign` (`paper_color_option_value_id`),
  KEY `papers_paper_weight_option_value_id_foreign` (`paper_weight_option_value_id`),
  CONSTRAINT `papers_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `papers_paper_color_option_value_id_foreign` FOREIGN KEY (`paper_color_option_value_id`) REFERENCES `erp_options` (`id`),
  CONSTRAINT `papers_paper_type_option_value_id_foreign` FOREIGN KEY (`paper_type_option_value_id`) REFERENCES `erp_options` (`id`),
  CONSTRAINT `papers_paper_weight_option_value_id_foreign` FOREIGN KEY (`paper_weight_option_value_id`) REFERENCES `erp_options` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

