--
-- Table structure for table `product_options`
--

DROP TABLE IF EXISTS `product_options`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_options` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `option_group_id` bigint unsigned NOT NULL,
  `erp_option_id` bigint unsigned DEFAULT NULL,
  `option_code` varchar(100) DEFAULT NULL,
  `field_name` varchar(150) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `label` varchar(150) NOT NULL,
  `value` varchar(150) DEFAULT NULL,
  `additional_price` decimal(10,2) NOT NULL DEFAULT '0.00',
  `metadata` json DEFAULT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `deleted_by` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `product_options_option_group_id_foreign` (`option_group_id`),
  KEY `product_options_erp_option_id_foreign` (`erp_option_id`),
  CONSTRAINT `product_options_erp_option_id_foreign` FOREIGN KEY (`erp_option_id`) REFERENCES `erp_options` (`id`) ON DELETE SET NULL,
  CONSTRAINT `product_options_option_group_id_foreign` FOREIGN KEY (`option_group_id`) REFERENCES `product_option_groups` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=12648 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

