CREATE TABLE `product_shopping_setting_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `shopping_setting_id` bigint unsigned NOT NULL,
  `shopping_setting_item_id` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `prod_shop_setting_unique` (`product_id`,`shopping_setting_id`),
  KEY `product_shopping_setting_items_shopping_setting_id_foreign` (`shopping_setting_id`),
  KEY `product_shopping_setting_items_shopping_setting_item_id_foreign` (`shopping_setting_item_id`),
  CONSTRAINT `product_shopping_setting_items_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `product_shopping_setting_items_shopping_setting_id_foreign` FOREIGN KEY (`shopping_setting_id`) REFERENCES `shopping_settings` (`id`) ON DELETE CASCADE,
  CONSTRAINT `product_shopping_setting_items_shopping_setting_item_id_foreign` FOREIGN KEY (`shopping_setting_item_id`) REFERENCES `shopping_setting_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
