--
-- Table structure for table `products`
--

DROP TABLE IF EXISTS `products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `products` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `category_id` bigint unsigned NOT NULL,
  `sku` varchar(100) DEFAULT NULL,
  `slug` varchar(200) NOT NULL,
  `name` varchar(200) NOT NULL,
  `name_en` varchar(100) DEFAULT NULL,
  `name_ja` varchar(100) DEFAULT NULL,
  `price` decimal(15,2) NOT NULL,
  `compare_price` decimal(15,2) DEFAULT NULL,
  `stock_quantity` int NOT NULL DEFAULT '0',
  `min_quantity` int NOT NULL DEFAULT '1',
  `max_quantity` int DEFAULT NULL,
  `short_description` text,
  `description` text,
  `images` json DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `allow_file_upload` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Allow file upload design mode',
  `allow_web_editor` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Allow web editor design mode',
  `is_blank_canvas` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Blank canvas mode (no template)',
  `is_popular` tinyint(1) NOT NULL DEFAULT '0',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `sort_order` int NOT NULL DEFAULT '0',
  `view_count` int NOT NULL DEFAULT '0',
  `exposure_count` int unsigned NOT NULL DEFAULT '0' COMMENT 'Times exposed to users',
  `average_rating` decimal(3,2) NOT NULL DEFAULT '0.00',
  `total_reviews` int unsigned NOT NULL DEFAULT '0',
  `total_rating` int unsigned NOT NULL DEFAULT '0',
  `branch_name` varchar(255) DEFAULT NULL COMMENT 'Branch name for admin filter',
  `client_name` varchar(255) DEFAULT NULL COMMENT 'Client name for admin filter',
  `requires_separate_shipping` tinyint(1) NOT NULL DEFAULT '0' COMMENT '따로 보내야 하는 품목 (e.g. standee, signboard) — charged separately per item',
  `separate_shipping_fee` decimal(10,2) DEFAULT '0.00' COMMENT 'Extra shipping fee per item when requires_separate_shipping = true',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `web_editor_id` bigint unsigned DEFAULT NULL,
  `info_icon` json DEFAULT NULL COMMENT 'Product info icon configuration',
  PRIMARY KEY (`id`),
  UNIQUE KEY `products_slug_unique` (`slug`),
  UNIQUE KEY `products_sku_unique` (`sku`),
  KEY `products_category_id_is_active_index` (`category_id`,`is_active`),
  KEY `products_is_popular_is_active_index` (`is_popular`,`is_active`),
  KEY `products_exposure_count_index` (`exposure_count`),
  KEY `products_web_editor_id_index` (`web_editor_id`),
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_web_editor_id_foreign` FOREIGN KEY (`web_editor_id`) REFERENCES `web_editors` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=74 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

