--
-- Table structure for table `templates`
--

DROP TABLE IF EXISTS `templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `templates` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL COMMENT 'Template name',
  `file_path` varchar(500) DEFAULT NULL COMMENT 'Source file path (e.g., AI or PDF format)',
  `specifications` json DEFAULT NULL COMMENT 'Detailed template specifications in JSON format',
  `safety_line` json DEFAULT NULL COMMENT 'Safety margin guidelines',
  `cut_line` json DEFAULT NULL COMMENT 'Cutting/Trim guidelines',
  `font_set` json DEFAULT NULL COMMENT 'Predefined font configurations',
  `color_set` json DEFAULT NULL COMMENT 'Predefined color palette',
  `spot_color` json DEFAULT NULL COMMENT 'Spot color/Special ink settings',
  `layout_config` json DEFAULT NULL COMMENT 'Field mapping for Simple Text and Web Editors',
  `editor_permission` json DEFAULT NULL COMMENT 'Permission settings for template editing',
  `front_preview_url` varchar(500) DEFAULT NULL COMMENT 'Rendered preview image for front side',
  `back_preview_url` varchar(500) DEFAULT NULL COMMENT 'Rendered preview image for back side',
  `preview_images` json DEFAULT NULL COMMENT 'Additional gallery of preview images',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Active status for visibility',
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `size_option_id` bigint unsigned DEFAULT NULL,
  `type` varchar(255) DEFAULT NULL COMMENT 'Fold type of the template',
  `orientation` varchar(255) DEFAULT NULL COMMENT 'Print orientation',
  `side` varchar(255) DEFAULT NULL COMMENT 'Number of sides',
  `web_editor_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `templates_product_id_is_active_index` (`is_active`),
  KEY `templates_is_active_index` (`is_active`),
  KEY `templates_created_by_index` (`created_by`),
  KEY `templates_created_at_index` (`created_at`),
  KEY `templates_size_option_id_index` (`size_option_id`),
  KEY `templates_web_editor_id_index` (`web_editor_id`),
  CONSTRAINT `templates_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `templates_size_option_id_foreign` FOREIGN KEY (`size_option_id`) REFERENCES `erp_size_options` (`id`) ON DELETE SET NULL,
  CONSTRAINT `templates_web_editor_id_foreign` FOREIGN KEY (`web_editor_id`) REFERENCES `web_editors` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

