--
-- Table structure for table `unit_prices`
--

DROP TABLE IF EXISTS `unit_prices`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `unit_prices` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `erp_size_option_id` bigint unsigned DEFAULT NULL,
  `erp_paper_option_id` bigint unsigned DEFAULT NULL,
  `product_id` bigint unsigned NOT NULL,
  `erp_subject_master_option_id` bigint unsigned DEFAULT NULL,
  `product_type` varchar(255) DEFAULT NULL,
  `combination_options` json DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `unit_prices_erp_paper_option_id_foreign` (`erp_paper_option_id`),
  KEY `unit_prices_product_id_foreign` (`product_id`),
  KEY `unit_prices_product_type_index` (`product_type`),
  KEY `unit_prices_is_active_index` (`is_active`),
  KEY `unit_prices_erp_size_option_id_erp_paper_option_id_index` (`erp_size_option_id`,`erp_paper_option_id`),
  KEY `unit_prices_erp_subject_master_option_id_foreign` (`erp_subject_master_option_id`),
  CONSTRAINT `unit_prices_erp_paper_option_id_foreign` FOREIGN KEY (`erp_paper_option_id`) REFERENCES `erp_options` (`id`) ON DELETE SET NULL,
