DROP TABLE IF EXISTS `upload_art_works`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `upload_art_works` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `design_group_id` bigint unsigned NOT NULL,
  `url` varchar(255) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `size` varchar(255) DEFAULT NULL,
  `mime` varchar(255) DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `print_as_is` tinyint(1) NOT NULL DEFAULT '0',
  `print_without_proof` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `upload_art_works_design_group_id_foreign` (`design_group_id`),
  CONSTRAINT `upload_art_works_design_group_id_foreign` FOREIGN KEY (`design_group_id`) REFERENCES `design_groups` (`id`) ON DELETE CASCADE
