DROP TABLE IF EXISTS `user_coupons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_coupons` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `coupon_id` bigint unsigned NOT NULL,
  `received_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '수령일 (Received Date)',
  `used_at` timestamp NULL DEFAULT NULL COMMENT '사용일 (Used Date)',
  `order_id` bigint unsigned DEFAULT NULL,
  `status` enum('available','used','expired','upcoming') NOT NULL DEFAULT 'available' COMMENT '상태 (Status)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_coupons_user_id_coupon_id_unique` (`user_id`,`coupon_id`),
  KEY `user_coupons_order_id_foreign` (`order_id`),
  KEY `user_coupons_user_id_status_index` (`user_id`,`status`),
  KEY `user_coupons_coupon_id_status_index` (`coupon_id`,`status`),
  KEY `user_coupons_received_at_index` (`received_at`),
